{
  "name": "pairwise_advantage_loss",
  "intuition": "This loss encourages preference for higher advantage signals by weighting the difference in advantages between pairs, normalizing to mitigate scale issues, and applying a sigmoid to focus on preference confidence. It directly promotes pairs where the advantage difference indicates clear preference, aligning with the goal of preference modeling in RL4CO.",
  "pseudocode": "loss = mean(sigma(logsigmoid(advantage_w - advantage_l))) based on pairwise advantage differences, normalized to stabilize scale.",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "scale_stabilized",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "sigmoid", "mean", "sub", "div", "log", "abs"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    weight = batch[\"weight\"]\n    adv_diff = ops.sub(advantage_w, advantage_l)\n    adv_diff_norm = ops.div(adv_diff, ops.max(ops.abs(adv_diff)), ops.epsilon)\n    preference = ops.logsigmoid(adv_diff_norm)\n    weighted_pref = ops.mul(preference, weight)\n    mean_pref = ops.mean(weighted_pref)\n    loss_value = ops.sigmoid(mean_pref)\n    return loss_value"
}

{
  "name": "loss_advantage_ratio_exp_neg",
  "intuition": "leverages an exponential decay of the negative ratio between log-prob difference and advantage gap, promoting pairs where the model confidently favors winning samples proportional to their advantage; shifts paradigm from margin/logsigmoid to ratio-scaled exp loss",
  "pseudocode": "ratio = (lpw - lpl) / (adv_gap + epsilon)\nloss = exp(-clamp(ratio, -10, 10))\nweighted_loss = weight * loss\nreturn mean(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_ratio",
    "signal_family": "advantage_gap",
    "link_family": "exp_neg",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": ["exp", "neg", "clamp", "add", "div", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_gap = batch['advantage_gap']\n    eps = 1e-6\n    ratio = ops.div(ops.sub(lpw, lpl), ops.add(ops.abs(adv_gap), eps))\n    ratio_clamped = ops.clamp(ratio, -10.0, 10.0)\n    loss = ops.exp(ops.neg(ratio_clamped))\n    loss_weighted = ops.mul(loss, weight)\n    return ops.mean(loss_weighted)"
}

{
  "name": "loss_logsigmoid_000_cost_sum",
  "intuition": "Pairwise logsigmoid loss similar to parent but with sum aggregation replacing mean to emphasize total loss.",
  "pseudocode": "loss = -logsigmoid(clamp(alpha*scale*(lpw - lpl) - 0.1 * (cost_b - cost_a), -20, 20))\nweighted_loss = loss * weight\nfinal_loss = sum(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
